		Deps      []string
		PkgPath   string
		Srcs      []string
		TestSrcs  []string
		TestData  []string
		PluginFor []string
		EmbedSrcs []string
		// The visibility property is unused in blueprint, but exists so that soong
		// can add one and not have the bp files fail to parse during the bootstrap build.
		Visibility []string

